-- ============================================================
-- WorkTracker -- one-time import of Podatki/Vzorčenje vzorcev2026.xlsx
-- Standalone table, no FKs to any existing WorkTracker/CRM tables.
-- Run in: Supabase Dashboard -> SQL Editor -> New Query
-- ============================================================
--
-- Source: 22 sheets (20 dated logs 21.01.2026-14.09.2026, plus the
-- VZORČENJE and OSTANKI summary sheets -- confirmed zero sample_no
-- overlap with the dated sheets, so all 22 are distinct data, not
-- duplicates). source_sheet on every row records which tab it came
-- from. GERK/FMS/Sample no (and occasionally Datum vzorčenja) were
-- Excel row-merged across grouped samples of the same field --
-- forward-filled from the merge's top cell during extraction so every
-- row carries its real value, not a blank.
--
-- datum_vzorcenja/datum_posiljanja are stored as raw text as they
-- appear in the sheet -- both columns mix real dates (various D.M.
-- or D.M.YYYY formats) with free-text notes ("bb", "se ne vzorči",
-- "ni bil narejen", "zamuja", etc). Per the business rule: a row
-- whose datum_posiljanja parses as a real date was actually sent.
-- No parsing/validation applied here -- left as-is for a later pass.
--
-- RLS is enabled with no policies (service_role/dashboard only) --
-- this is a raw staging import with no defined access model yet.
--
-- KNOWN ISSUE -- OSTANKI only: from row "Vrtič" onward (~84 of its 134
-- rows, source_sheet = 'OSTANKI'), the source sheet itself has an
-- extra, undeclared column inserted after GERK (sometimes holding an
-- Ha value, sometimes blank) that isn't reflected in its header row --
-- shifting fms/sample_no/priimek one column right of where they
-- belong for those rows (e.g. an Ha value like 0.1437 lands in `fms`,
-- the real fms/sample_no values shift over, and the surname lands in
-- `datum_vzorcenja`). Every other sheet (all 20 dated logs +
-- VZORČENJE) was checked and is clean. Imported as-is as a known,
-- accepted limitation -- do not treat OSTANKI's fms/sample_no/priimek/
-- datum_vzorcenja as reliable without manually re-checking against
-- the source spreadsheet first.

create table public.vzorcenje_uvoz_2026 (
    id               uuid primary key default gen_random_uuid(),
    source_sheet     text not null,
    gerk             text,
    fms              text,
    sample_no        text,
    priimek          text,
    datum_vzorcenja  text,
    datum_posiljanja text,
    lrr              text,
    created_at       timestamptz not null default now()
);

alter table public.vzorcenje_uvoz_2026 enable row level security;

